mapper.select:
/* SQL ID : QstnDAO.qstnList 설 명 : 문항목록조회 */ SELECT QSTN.QSTN_ID , QSTN.EXAM_DTL_ID , QSTN.QSTN_TTL , DBMS_LOB.SUBSTR(QSTN.QSTN_CTS, 4000) AS QSTN_CTS , QSTN.QSTN_SEQNO , QSTN.QSTN_CNDDT_SEQNO , QSTN.QSTN_GBNCD , QSTN.QSTN_RSPNS_TYCD , QSTN.QSTN_SCR , QSTN.QSTN_DFCTLV_TYCD , QSTN.CRANS_TYCD , QSTN.EXRCS_SDDN_QSTN_BSC_ID , QSTN.CRANS_EXPLN , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'QSTN_RSPNS_TYCD' AND CD = QSTN.QSTN_RSPNS_TYCD) AS QSTN_RSPNS_TYNM FROM TB_LMS_QSTN QSTN WHERE QSTN.DELYN = 'N'
AND QSTN.EXAM_DTL_ID = #{examDtlId}
AND QSTN.EXRCS_SDDN_QSTN_BSC_ID = #{exrcsSddnQstnBscId}
AND QSTN.QSTN_GBNCD = #{qstnGbncd} ORDER BY QSTN.QSTN_SEQNO, QSTN.QSTN_CNDDT_SEQNO

		/*
             SQL ID : QstnDAO.qstnCntSelect
             설  명 : 문항개수조회
         */
        SELECT
			COUNT(*)
		  FROM TB_LMS_QSTN
		 WHERE DELYN = 'N'


			   AND EXAM_DTL_ID = #{examDtlId}


			   AND EXRCS_SDDN_QSTN_BSC_ID = #{exrcsSddnQstnBscId}


		   AND QSTN_GBNCD = #{qstnGbncd}
		   AND QSTN_CNDDT_SEQNO = 1

mapper.insert:
		/*
             SQL ID : QstnDAO.qstnRegist
             설  명 : 문항등록
         */
         INSERT INTO TB_LMS_QSTN (
         	  QSTN_ID
			, EXAM_DTL_ID
			, EXRCS_SDDN_QSTN_BSC_ID
			, QSTN_TTL
			, QSTN_CTS
			, QSTN_SEQNO
			, QSTN_CNDDT_SEQNO
			, QSTN_GBNCD
			, QSTN_RSPNS_TYCD
			, QSTN_SCR
			, QSTN_DFCTLV_TYCD
			, CRANS_TYCD
			, CRANS_EXPLN
			, RGTR_ID
			, REG_DTTM
         ) VALUES (
         	  #{qstnId}
         	, #{examDtlId}
         	, #{exrcsSddnQstnBscId}
			, #{qstnTtl}
			, #{qstnCts}
			, #{qstnSeqno}
			, #{qstnCnddtSeqno}
			, #{qstnGbncd}
			, #{qstnRspnsTycd}
			, #{qstnScr}
			, #{qstnDfctlvTycd}
			, #{cransTycd}
			, #{cransExpln}
			, #{rgtrId}
			, FN_DTTM()
         )

mapper.update:
		/*
             SQL ID : QstnDAO.qstnModify
             설  명 : 문항수정
         */
         UPDATE TB_LMS_QSTN SET
          	  MDFR_ID   = #{mdfrId}
    		, MOD_DTTM = FN_DTTM()
    		, CRANS_TYCD = #{cransTycd}
    		, CRANS_EXPLN = #{cransExpln}

    		, QSTN_TTL = #{qstnTtl}


    		, QSTN_CTS = #{qstnCts}


    		, QSTN_RSPNS_TYCD = #{qstnRspnsTycd}


    		, QSTN_DFCTLV_TYCD = #{qstnDfctlvTycd}


    		, QSTN_SEQNO = #{qstnSeqno}

    	  WHERE QSTN_ID = #{qstnId}
    	    AND (EXAM_DTL_ID = #{examDtlId} OR EXRCS_SDDN_QSTN_BSC_ID = #{exrcsSddnQstnBscId})

mapper.select:
		/*
             SQL ID : QstnDAO.qstnSelect
             설  명 : 문항조회
         */
         SELECT
         	*
           FROM TB_LMS_QSTN
          WHERE QSTN_ID = #{qstnId}


			   AND EXAM_DTL_ID = #{examDtlId}


			   AND EXRCS_SDDN_QSTN_BSC_ID = #{exrcsSddnQstnBscId}


		   AND QSTN_GBNCD = #{qstnGbncd}

mapper.update:
		/*
             SQL ID : QstnDAO.qstnDelynModify
             설  명 : 문항삭제여부수정
         */
		UPDATE TB_LMS_QSTN SET
			  MDFR_ID = #{mdfrId}
			, MOD_DTTM = FN_DTTM()
			, DELYN = 'Y'
		 WHERE QSTN_SEQNO = #{qstnSeqno}
		   AND EXAM_DTL_ID = #{examDtlId}

		   AND QSTN_CNDDT_SEQNO = #{qstnCnddtSeqno}

/* SQL ID : QstnDAO.qstnDelNSeqnoModify 설 명 : 문항미삭제순번수정 */ MERGE INTO TB_LMS_QSTN QSTN USING ( SELECT EXAM_DTL_ID , EXRCS_SDDN_QSTN_BSC_ID , QSTN_SEQNO , (SELECT COUNT(*) FROM TB_LMS_QSTN WHERE EXAM_DTL_ID = #{examDtlId} AND DELYN = 'N' AND QSTN_SEQNO = #{qstnSeqno}) AS QSTN_CNT FROM TB_LMS_QSTN WHERE QSTN_SEQNO = #{qstnSeqno} AND EXAM_DTL_ID = #{examDtlId} AND QSTN_CNDDT_SEQNO = 1 AND ROWNUM = 1 ORDER BY QSTN_SEQNO, QSTN_CNDDT_SEQNO ) DEL_N_QSTN ON ( QSTN.EXAM_DTL_ID = DEL_N_QSTN.EXAM_DTL_ID AND QSTN.DELYN = 'N' ) WHEN MATCHED THEN UPDATE SET QSTN.MDFR_ID = #{mdfrId} , QSTN.MOD_DTTM = FN_DTTM()
, QSTN.QSTN_SEQNO = CASE WHEN DEL_N_QSTN.QSTN_CNT > 0 THEN QSTN.QSTN_SEQNO WHEN QSTN.QSTN_SEQNO > #{qstnSeqno} THEN QSTN.QSTN_SEQNO - 1 ELSE QSTN.QSTN_SEQNO END , QSTN.QSTN_CNDDT_SEQNO = CASE WHEN DEL_N_QSTN.QSTN_CNT > 0 AND DEL_N_QSTN.QSTN_SEQNO = #{qstnSeqno} AND QSTN.QSTN_CNDDT_SEQNO > #{qstnCnddtSeqno} THEN QSTN.QSTN_CNDDT_SEQNO - 1 ELSE QSTN.QSTN_CNDDT_SEQNO END
, QSTN.QSTN_SEQNO = QSTN.QSTN_SEQNO - 1

		/*
             SQL ID : QstnDAO.quizQstnScrModify
             설  명 : 퀴즈문항점수수정
         */
         UPDATE TB_LMS_QSTN SET
         	  MDFR_ID = #{mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, QSTN_SCR = #{qstnScr}
          WHERE EXAM_DTL_ID = #{examDtlId}
            AND QSTN_SEQNO = #{qstnSeqno}

		/*
             SQL ID : QstnDAO.cmptnYQuizQstnScrBulkModify
             설  명 : 출제완료퀴즈문항점수일괄수정
         */

         UPDATE TB_LMS_QSTN SET
         	  MDFR_ID = #{item.mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, QSTN_SCR = #{item.qstnScr}
          WHERE EXAM_DTL_ID = #{item.examDtlId}
            AND DELYN = 'N'
            AND QSTN_SEQNO = #{item.qstnSeqno}

mapper.insert:
/* SQL ID : QstnDAO.quizQstnCopy 설 명 : 퀴즈문항가져오기 */ INSERT INTO TB_LMS_QSTN ( QSTN_ID , EXAM_DTL_ID , QSTN_TTL , QSTN_CTS , QSTN_RSPNS_TYCD , QSTN_DFCTLV_TYCD , CRANS_TYCD , QSTN_SEQNO , RGTR_ID , REG_DTTM , QSTN_GBNCD , QSTN_CNDDT_SEQNO ) SELECT A.* , ROW_NUMBER() OVER(ORDER BY QSTN_TTL) AS QSTN_CNDDT_SEQNO FROM (
SELECT #{item.qstnId} AS QSTN_ID , #{item.examDtlId} AS EXAM_DTL_ID , COALESCE(Q.QSTN_TTL, B.QSTN_TTL) AS QSTN_TTL , COALESCE(Q.QSTN_CTS, B.QSTN_CTS) AS QSTN_CTS , COALESCE(Q.QSTN_RSPNS_TYCD, B.QSTN_RSPNS_TYCD) AS QSTN_RSPNS_TYCD , COALESCE(Q.QSTN_DFCTLV_TYCD, B.QSTN_DFCTLV_TYCD) AS QSTN_DFCTLV_TYCD , COALESCE(Q.CRANS_TYCD, B.CRANS_TYCD) AS CRANS_TYCD , (SELECT NVL(MAX(QSTN_SEQNO), 0) + 1 FROM TB_LMS_QSTN WHERE EXAM_DTL_ID = #{item.examDtlId} AND DELYN = 'N') AS QSTN_SEQNO , #{item.rgtrId} AS RGTR_ID , FN_DTTM() AS REG_DTTM , 'GENERAL' AS QSTN_GBNCD FROM DUAL LEFT JOIN TB_LMS_QSTN Q ON Q.QSTN_ID = #{item.copyQstnId} LEFT JOIN TB_LMS_QBNK_QSTN B ON B.QBNK_QSTN_ID = #{item.copyQstnId}
) A

		/*
             SQL ID : QstnDAO.qstnBulkRegist
             설  명 : 문항일괄등록
         */
         INSERT ALL

			INTO TB_LMS_QSTN (
	         	  QSTN_ID
				, EXAM_DTL_ID
				, EXRCS_SDDN_QSTN_BSC_ID
				, QSTN_TTL
				, QSTN_CTS
				, QSTN_SEQNO
				, QSTN_CNDDT_SEQNO
				, QSTN_GBNCD
				, QSTN_RSPNS_TYCD
				, QSTN_SCR
				, QSTN_DFCTLV_TYCD
				, CRANS_TYCD
				, RGTR_ID
				, REG_DTTM
	         ) VALUES (
	         	  #{item.qstnId}
	         	, #{item.examDtlId}
	         	, #{item.exrcsSddnQstnBscId}
				, #{item.qstnTtl}
				, #{item.qstnCts}
				, #{item.qstnSeqno}
				, #{item.qstnCnddtSeqno}
				, #{item.qstnGbncd}
				, #{item.qstnRspnsTycd}
				, #{item.qstnScr}
				, #{item.qstnDfctlvTycd}
				, #{item.cransTycd}
				, #{item.rgtrId}
				, FN_DTTM()
	         )

		SELECT * FROM DUAL

mapper.update:
		/*
             SQL ID : QstnDAO.exrcsSddnQstnBulkModify
             설  명 : 연습돌발문항일괄수정
         */

         UPDATE TB_LMS_QSTN SET
         	  MDFR_ID = #{item.mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, CRANS_TYCD = #{item.cransTycd}
         	, QSTN_TTL = #{item.qstnTtl}
         	, QSTN_CTS = #{item.qstnCts}
         	, QSTN_RSPNS_TYCD = #{item.qstnRspnsTycd}
         	, QSTN_DFCTLV_TYCD = #{item.qstnDfctlvTycd}
          WHERE DELYN = 'N'
            AND EXRCS_SDDN_QSTN_BSC_ID = #{item.exrcsSddnQstnBscId}
            AND QSTN_SEQNO = #{item.qstnSeqno}

/* SQL ID : QstnDAO.exrcsQstnBulkQstnSeqnoModify 설 명 : 연습문제일괄문항순번수정 */ MERGE INTO TB_LMS_QSTN QSTN USING ( SELECT * FROM (
SELECT EXRCS_SDDN_QSTN_BSC_ID , QSTN_ID , QSTN_SEQNO , #{item.qstnSeqno} AS NEW_QSTN_SEQNO , #{item.searchKey} AS CURRENT_QSTN_SEQNO , #{item.mdfrId} AS MDFR_ID FROM TB_LMS_QSTN WHERE DELYN = 'N' AND EXRCS_SDDN_QSTN_BSC_ID = #{item.exrcsSddnQstnBscId}
) A WHERE A.QSTN_SEQNO BETWEEN LEAST(A.NEW_QSTN_SEQNO, A.CURRENT_QSTN_SEQNO) AND GREATEST(A.NEW_QSTN_SEQNO, A.CURRENT_QSTN_SEQNO) ) OLD_QSTN ON ( QSTN.EXRCS_SDDN_QSTN_BSC_ID = OLD_QSTN.EXRCS_SDDN_QSTN_BSC_ID AND QSTN.QSTN_ID IN (OLD_QSTN.QSTN_ID) ) WHEN MATCHED THEN UPDATE SET QSTN.MDFR_ID = OLD_QSTN.MDFR_ID , QSTN.MOD_DTTM = FN_DTTM() , QSTN.QSTN_SEQNO = CASE WHEN QSTN.QSTN_SEQNO = OLD_QSTN.CURRENT_QSTN_SEQNO THEN OLD_QSTN.NEW_QSTN_SEQNO WHEN OLD_QSTN.CURRENT_QSTN_SEQNO > OLD_QSTN.NEW_QSTN_SEQNO THEN QSTN.QSTN_SEQNO + 1 ELSE QSTN.QSTN_SEQNO - 1 END

		/*
             SQL ID : QstnDAO.exrcsQstnBulkDelynModify
             설  명 : 연습문제일괄삭제여부수정
         */

         UPDATE TB_LMS_QSTN SET
         	  MDFR_ID = #{item.mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, DELYN = 'Y'
          WHERE QSTN_SEQNO = #{item.qstnSeqno}
            AND EXRCS_SDDN_QSTN_BSC_ID = #{item.exrcsSddnQstnBscId}

		/*
             SQL ID : QstnDAO.exrcsQstnBulkDelNSeqnoModify
             설  명 : 연습문제일괄미삭제순번수정
         */

		UPDATE TB_LMS_QSTN SET
		      MDFR_ID  = #{item.mdfrId}
		    , MOD_DTTM = FN_DTTM()
		    , QSTN_SEQNO = QSTN_SEQNO - 1
		 WHERE EXRCS_SDDN_QSTN_BSC_ID = #{item.exrcsSddnQstnBscId}
		   AND DELYN = 'N'
		   AND QSTN_SEQNO  >  #{item.qstnSeqno}

mapper.select:
/* SQL ID : QstnDAO.exrcsSddnQstnIdList 설 명 : 연습돌발문항아이디목록 */ SELECT QSTN_ID FROM TB_LMS_QSTN WHERE DELYN = 'N' AND (EXRCS_SDDN_QSTN_BSC_ID, QSTN_SEQNO) IN (
(#{item.exrcsSddnQstnBscId}, #{item.qstnSeqno})
)

mapper.insert:
/* SQL ID : QstnDAO.exrcsQstnCopy 설 명 : 연습문제가져오기 */ INSERT INTO TB_LMS_QSTN ( QSTN_ID , EXRCS_SDDN_QSTN_BSC_ID , QSTN_TTL , QSTN_CTS , QSTN_RSPNS_TYCD , QSTN_DFCTLV_TYCD , CRANS_TYCD , RGTR_ID , QSTN_SEQNO , QSTN_CNDDT_SEQNO , QSTN_GBNCD , REG_DTTM ) WITH BASE_SEQNO_CTE AS ( SELECT EXRCS_SDDN_QSTN_BSC_ID , NVL(MAX(QSTN_SEQNO), 0) AS BASE_SEQNO FROM TB_LMS_QSTN WHERE DELYN = 'N' GROUP BY EXRCS_SDDN_QSTN_BSC_ID ) SELECT A.* , NVL(C.BASE_SEQNO, 0) + ROW_NUMBER() OVER ( PARTITION BY A.EXRCS_SDDN_QSTN_BSC_ID ORDER BY A.QSTN_ID ) AS QSTN_SEQNO , 1 , 'EXRCS_QSTN' , FN_DTTM() FROM (
SELECT #{item.qstnId} AS QSTN_ID , #{item.exrcsSddnQstnBscId} AS EXRCS_SDDN_QSTN_BSC_ID , COALESCE(Q.QSTN_TTL, B.QSTN_TTL) AS QSTN_TTL , COALESCE(Q.QSTN_CTS, B.QSTN_CTS) AS QSTN_CTS , COALESCE(Q.QSTN_RSPNS_TYCD, B.QSTN_RSPNS_TYCD) AS QSTN_RSPNS_TYCD , COALESCE(Q.QSTN_DFCTLV_TYCD, B.QSTN_DFCTLV_TYCD) AS QSTN_DFCTLV_TYCD , COALESCE(Q.CRANS_TYCD, B.CRANS_TYCD) AS CRANS_TYCD , #{item.rgtrId} AS RGTR_ID FROM DUAL LEFT JOIN TB_LMS_QSTN Q ON Q.QSTN_ID = #{item.copyQstnId} LEFT JOIN TB_LMS_QBNK_QSTN B ON B.QBNK_QSTN_ID = #{item.copyQstnId}
) A LEFT JOIN BASE_SEQNO_CTE C ON C.EXRCS_SDDN_QSTN_BSC_ID = A.EXRCS_SDDN_QSTN_BSC_ID

mapper.select:
		/*
             SQL ID : QstnDAO.lctrWknoRegistQstnCntSelect
             설  명 : 강의주차등록문항수조회
         */
        SELECT COUNT(*) AS CNT
		  FROM (
		  	SELECT
				*
			  FROM TB_LMS_EXRCS_SDDN_QSTN_BSC SDDN
			  JOIN TB_LMS_QSTN QSTN
			    ON SDDN.EXRCS_SDDN_QSTN_BSC_ID = QSTN.EXRCS_SDDN_QSTN_BSC_ID
			   AND QSTN.DELYN = 'N'

			   	AND QSTN.EXRCS_SDDN_QSTN_BSC_ID  <>  #{exrcsSddnQstnBscId}

			 WHERE SDDN.DELYN = 'N'
			   AND SDDN.QSTN_GBNCD = #{qstnGbncd}
			   AND SDDN.SBJCT_ID = #{sbjctId}
			   AND SDDN.LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
			   AND QSTN.QSTN_SEQNO = #{qstnSeqno}
		  ) A

mapper.delete:
		/*
             SQL ID : QstnDAO.qstnListAllDelete
             설  명 : 문항목록전체삭제
         */
        DELETE FROM TB_LMS_QSTN
         WHERE EXRCS_SDDN_QSTN_BSC_ID = #{id}
            OR EXAM_DTL_ID IN (
         	    	SELECT
         	    		EXAM_DTL_ID
         	    	  FROM TB_LMS_EXAM_DTL
         	    	 WHERE EXAM_BSC_ID = #{id}
         	    )
